const dealer = $input.item.json.dealer || "";
const tipoRaw = String($input.item.json.tipo_media || "").toLowerCase().trim();
const tipo = tipoRaw || "bienvenida";
const canal = ($input.item.json.canal || "whatsapp").toLowerCase().trim();
const modelo = String($input.item.json.modelo || "").toUpperCase().trim();

// PENDIENTE: reemplazar con URLs reales de fotos/videos de inventario (insumo externo del cliente, ver Estado del Proyecto.md).
// Estructura esperada una vez haya datos reales:
// { "CW": { "bienvenida": "https://...mp4", "vehiculos": { "TOYOTA CAMRY 2023": "https://...mp4" } }, "RANCES": {...} }
const database = {};

const dealerData = database[dealer] || {};
let url = null;
if (tipo === "vehiculo" && modelo) {
  url = (dealerData.vehiculos || {})[modelo] || null;
} else {
  url = dealerData[tipo] || null;
}

return [{
  json: {
    contactId: $input.item.json.contactId,
    canal,
    dealer,
    media_disponible: url !== null,
    attachments: url ? [url] : []
  }
}];
